import XCTest

class DismissDialogAndOpenCreateRoom: XCTestCase {

    func testCreateRoom() throws {
        let app = XCUIApplication()
        app.launch()

        // Try to dismiss any alert by tapping Cancel
        let cancelButton = app.buttons["Cancel"]
        if cancelButton.waitForExistence(timeout: 2) {
            cancelButton.tap()
        }

        // Wait a moment
        sleep(1)

        // Try to find and tap the compose/create button
        // Look for buttons with "+" or compose-related names
        let composeButton = app.buttons.matching(NSPredicate(format: "label CONTAINS '+' OR label CONTAINS 'Compose' OR label CONTAINS 'create'")).firstMatch
        if composeButton.exists {
            composeButton.tap()
        } else {
            // Try by accessibility identifier
            let altButton = app.buttons.matching(NSPredicate(format: "identifier CONTAINS 'compose' OR identifier CONTAINS 'create'")).firstMatch
            if altButton.exists {
                altButton.tap()
            }
        }

        XCTAssertTrue(true)
    }
}
EOF

